template.solver:
def solve(t):
    for d in range(0, 81):
        for a in range(1, 151):
            b = a + d
            if b < 1:
                continue
            P = a * b
            found = False
            for x in range(1, a + 1):
                lo = -((-(P - 2 * t)) // (2 * x))
                hi = (P + 2 * t) // (2 * x)
                if lo < 1:
                    lo = 1
                if hi > b:
                    hi = b
                if lo <= hi:
                    found = True
                    break
            if not found:
                return d
    return -1
